const inputPrompt = items[0];

const content = [
  {
    type: "text",
    text: inputPrompt
  }
];

// Get the stitched image from the first (and only) item
const item = items[0];
if (item && item.binary && item.binary.data) {
  const binaryData = item.binary.data;
  const base64 = binaryData.data;
  const mimeType = binaryData.mimeType || "image/png";
  const dataUrl = `data:${mimeType};base64,${base64}`;

  content.push({
    type: "image_url",
    image_url: {
      url: dataUrl
    }
  });
} else {
  throw new Error("No stitched image found in input");
}

return [
  {
    json: {
      payload: {
        model: "gpt-4o", // Note: using gpt-4o as it has better vision capabilities
        messages: [
          {
            role: "user",
            content
          }
        ],
        max_tokens: 2000 // Increased for more detailed responses
      }
    }
  }
];

