// Parse the AI response
const response = $input.first().json.output;

// Function to clean and extract JSON
function extractAndParseJSON(text) {
  if (!text || typeof text !== 'string') {
    throw new Error('Invalid input: expected a string');
  }

  // Remove single-line comments (// ...) and multi-line comments (/* ... */)
  let cleaned = text
    .replace(/\/\/.*$/gm, '')
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .trim();

  // Try parsing the cleaned text directly
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    // If direct parsing fails, try to extract JSON patterns
    const jsonPatterns = [
      // Try to find complete JSON objects
      /\{[\s\S]*\}/,
      // Try to find JSON arrays
      /\[[\s\S]*\]/,
      // Try to find JSON between code blocks or quotes
      /```(?:json)?\s*(\{[\s\S]*?\})\s*```/i,
      /```(?:json)?\s*($$[\s\S]*?$$)\s*```/i,
      // Try to find JSON between specific markers
      /json\s*[:\-=]\s*(\{[\s\S]*?\})/i,
      /json\s*[:\-=]\s*(\[[\s\S]*?\])/i
    ];

    for (const pattern of jsonPatterns) {
      const match = cleaned.match(pattern);
      if (match) {
        try {
          const jsonStr = match[1] || match[0];
          return JSON.parse(jsonStr.trim());
        } catch (parseError) {
          continue; // Try next pattern
        }
      }
    }

    // Last resort: try to find any valid JSON substring
    for (let i = 0; i < cleaned.length; i++) {
      if (cleaned[i] === '{' || cleaned[i] === '[') {
        let braceCount = 0;
        let bracketCount = 0;
        let endIndex = i;

        for (let j = i; j < cleaned.length; j++) {
          if (cleaned[j] === '{') braceCount++;
          if (cleaned[j] === '}') braceCount--;
          if (cleaned[j] === '[') bracketCount++;
          if (cleaned[j] === ']') bracketCount--;

          if (braceCount === 0 && bracketCount === 0 && j > i) {
            endIndex = j;
            break;
          }
        }

        if (endIndex > i) {
          try {
            const candidate = cleaned.substring(i, endIndex + 1);
            return JSON.parse(candidate);
          } catch (parseError) {
            continue;
          }
        }
      }
    }

    throw new Error(`Could not parse AI response as JSON. Original error: ${e.message}`);
  }
}

try {
  const parsed = extractAndParseJSON(response);
  return parsed;
} catch (error) {
  // Return a structured error response instead of throwing
  return {
    error: true,
    message: error.message,
    originalResponse: response,
    timestamp: new Date().toISOString()
  };
}

// Get the input text
const inputText = $input.first().json.result.content[0].text; // Adjust field name as needed

// Check if it's a simple message (no colons or very short)
const hasStructuredData = inputText.includes(':') && inputText.split('\n').length > 1;

if (!hasStructuredData) {
  // Handle simple messages like "you are not connected to the server"
  return [{
    json: {
      error: true,
      message: inputText.trim(),
      connected: false
    }
  }];
}

// Parse structured server info
const lines = inputText.split('\n');
const result = {
  error: false,
  connected: true
};

lines.forEach(line => {
  // Skip empty lines
  if (line.trim() === '') return;

  // Split on the first colon to separate key and value
  const colonIndex = line.indexOf(':');
  if (colonIndex === -1) return;

  const key = line.substring(0, colonIndex).trim();
  const value = line.substring(colonIndex + 1).trim();

  // Convert key to camelCase and clean it up
  const cleanKey = key
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, '') // Remove special characters
    .replace(/\s+(.)/g, (match, letter) => letter.toUpperCase()) // Convert to camelCase
    .replace(/\s/g, ''); // Remove remaining spaces

  // Try to convert numeric values
  let parsedValue = value;
  if (!isNaN(value) && value !== '') {
    parsedValue = parseFloat(value);
  }

  result[cleanKey] = parsedValue;
});

// Return the formatted JSON
return [{ json: result }];

const data = $input.all(); // This gets an array of input items

const filteredResults = data
  .filter(item => item.json.function_called && item.json.result)
  .map(item => ({
    function_called: item.json.function_called,
    result: item.json.result
  }));

return { filteredResults };

const items = $input.all(); // All input items as an array
// This code runs ONCE, not once per item
return items.map(item => ({
  json: { ...item.json, processed: true }
}));
